const items = $input.all();
const today = new Date().toISOString().split('T')[0]; // Current date YYYY-MM-DD
const eligibleLeads = [];

for (const item of items) {
  const row = item.json;

  // Stop Condition: Only process active leads scheduled for today or earlier
  if (row['Lead Status'] === 'Active' && row['Next Follow-Up Date'] && row['Next Follow-Up Date'] <= today) {
    const currentStage = row['Follow-Up Stage'] || 'Stage 0';
    let nextStage = 'Stage 1';
    let nextOffsetDays = 1; // Default next interval
    let messageBody = '';
    let subject = '';

    const name = row['Full Name'] || 'there';
    const address = row['Property Address'] || 'the property';

    // 5-Stage Cadence Logic
    switch (currentStage) {
      case 'Stage 0': // Move to Stage 1 (Day 1 touch)
        nextStage = 'Stage 1';
        nextOffsetDays = 2; // Next touch in 2 days (Day 3)
        subject = `Tour confirmation for ${address}`;
        messageBody = `Hi ${name}, Marcus here from the brokerage. Did you get a chance to review the photos and floor plan for ${address}? Let me know if you would like me to set up a private walkthrough this week.`;
        break;

      case 'Stage 1': // Move to Stage 2 (Day 3 touch)
        nextStage = 'Stage 2';
        nextOffsetDays = 4; // Next touch in 4 days (Day 7)
        subject = `Market update near ${address}`;
        messageBody = `Hi ${name}, two comparable properties just went under contract near ${address}. Are you still actively evaluating homes in this neighborhood, or has your search shifted?`;
        break;

      case 'Stage 2': // Move to Stage 3 (Day 7 touch)
        nextStage = 'Stage 3';
        nextOffsetDays = 7; // Next touch in 7 days (Day 14)
        subject = `Weekend showings for ${address}`;
        messageBody = `Hey ${name}, I am coordinating showing blocks for this coming Saturday. Do you have 15 minutes available to tour ${address} or similar listings in the area?`;
        break;

      case 'Stage 3': // Move to Stage 4 (Day 14 touch - The 9-word closing check)
        nextStage = 'Stage 4';
        nextOffsetDays = 7; // Next touch in 7 days (Day 21)
        subject = `Quick question regarding ${address}`;
        messageBody = `Hi ${name}, are you still interested in purchasing a property in Austin this quarter?`;
        break;

      case 'Stage 4': // Move to Stage 5 (Day 21 - The Breakup Message)
        nextStage = 'Completed';
        nextOffsetDays = 0;
        subject = `Closing file for ${address}`;
        messageBody = `Hi ${name}, I have not heard back, so I assume your property search is on hold for now. I will close out your inquiry file so I don't crowd your inbox. Feel free to reach back out whenever you are ready!`;
        break;

      default:
        continue;
    }

    // Calculate next follow-up date
    const nextDate = new Date();
    nextDate.setDate(nextDate.getDate() + nextOffsetDays);
    const formattedNextDate = nextDate.toISOString().split('T')[0];

    eligibleLeads.push({
      json: {
        row_number: row.row_number || item.pairedItem?.item || 2,
        lead_id: row['Lead ID'],
        full_name: name,
        email: row['Email'],
        phone: row['Phone'],
        property_address: address,
        current_stage: currentStage,
        next_stage: nextStage,
        next_followup_date: nextStage === 'Completed' ? '' : formattedNextDate,
        lead_status: nextStage === 'Completed' ? 'Unresponsive' : 'Active',
        subject: subject,
        message: messageBody,
        processed_at: new Date().toISOString()
      }
    });
  }
}

return eligibleLeads;

